final Lock lock = new ReentrantLock();
StringBuilder sb = new StringBuilder();

Thread t1 = new Thread(() -> {
    for (int i = 0; i < 10; i++) {
        lock.lock();
        sb.append("T1");
        lock.unlock();
    }
});
Thread t2 = new Thread(() -> {
    for (int i = 0; i < 10; i++) {
        lock.lock();
        sb.append("T2");
        lock.unlock();
    }
});

t1.start();
t2.start();
try {
    t1.join();
    t2.join();
} catch (InterruptedException e) {
    e.printStackTrace();
}
out.println(sb);

